build(container: HTMLElement): void {
  container.innerHTML = `
    <div class="mycount-wrap">
      <label for="mycount-src">${t('mycount.label.src')}</label>
      <textarea id="mycount-src" rows="6"></textarea>
      <div class="mycount-res" aria-live="polite"></div>
      <button type="button" data-act="copy">${t('mycount.btn.copy')}</button>
    </div>`;

  const src = container.querySelector<HTMLTextAreaElement>('#mycount-src')!;
  const res = container.querySelector<HTMLElement>('.mycount-res')!;
  src.addEventListener('input', render);
  container.addEventListener('click', onClick);
  render();
}

// 입력칸에는 항상 이름
<label for="mycount-src">${t('mycount.label.src')}</label>
<textarea id="mycount-src"></textarea>

// 아이콘만 있는 단추에도 이름
<button type="button" data-act="clear" aria-label="${t('mycount.btn.clear')}">🗑</button>

// 결과·상태 자리는 읽히게
<div class="mycount-res" aria-live="polite"></div>
